def move_one_ball(arr):
    n = len(arr)
    if n == 0:
        return True

    # Find the index where the array breaks the non-decreasing order
    break_index = -1
    for i in range(n - 1):
        if arr[i] > arr[i + 1]:
            if break_index != -1:
                # More than one break point found, cannot be sorted by right shift
                return False
            break_index = i

    # If no break point is found, the array is already sorted
    if break_index == -1:
        return True

    # Check if the array can be sorted by right shift starting from break_index
    for i in range(break_index + 1, n - 1):
        if arr[i] > arr[i + 1]:
            return False

    # Check if the first element is greater than the last element
    if arr[0] > arr[-1]:
        return False

    return True
```

